{"sql": "-- Now let me compute the career span with ABS and rounding
SELECT 
  player_id,
  ROUND(ABS(EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))), 2) as rounded_years,
  ROUND(ABS(DATE_DIFF('month', 
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
    ), 
    TRY_CAST(final_game AS DATE)
  )), 2) as rounded_months,
  ROUND(ABS(DATE_DIFF('day',
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
      + INTERVAL (
        DATE_DIFF('month', 
          DATE_ADD(TRY_CAST(debut AS DATE), 
            INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
          ), 
          TRY_CAST(final_game AS DATE)
        )
      ) MONTH
    ),
    TRY_CAST(final_game AS DATE)
  )), 2) as rounded_days,
  ROUND(ABS(EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))), 2) 
  + ROUND(ABS(DATE_DIFF('month', 
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
    ), 
    TRY_CAST(final_game AS DATE)
  )), 2) / 12.0 
  + ROUND(ABS(DATE_DIFF('day',
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
      + INTERVAL (
        DATE_DIFF('month', 
          DATE_ADD(TRY_CAST(debut AS DATE), 
            INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
          ), 
          TRY_CAST(final_game AS DATE)
        )
      ) MONTH
    ),
    TRY_CAST(final_game AS DATE)
  )), 2) / 365.0 as career_span
FROM player 
WHERE debut IS NOT NULL AND debut != '' AND final_game IS NOT NULL AND final_game != ''
AND TRY_CAST(debut AS DATE) IS NOT NULL AND TRY_CAST(final_game AS DATE) IS NOT NULL
LIMIT 5", "preview_rows": 12}

{"sql": "-- Those are legitimate single-game players. The calculation seems correct.
-- Let me verify the average one more time with a cleaner query
SELECT ROUND(AVG(
  ROUND(ABS(EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))), 2) 
  + ROUND(ABS(DATE_DIFF('month', 
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
    ), 
    TRY_CAST(final_game AS DATE)
  )), 2) / 12.0 
  + ROUND(ABS(DATE_DIFF('day',
    DATE_ADD(TRY_CAST(debut AS DATE), 
      INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
      + INTERVAL (
        DATE_DIFF('month', 
          DATE_ADD(TRY_CAST(debut AS DATE), 
            INTERVAL (EXTRACT(YEAR FROM TRY_CAST(final_game AS DATE)) - EXTRACT(YEAR FROM TRY_CAST(debut AS DATE))) YEAR
          ), 
          TRY_CAST(final_game AS DATE)
        )
      ) MONTH
    ),
    TRY_CAST(final_game AS DATE)
  )), 2) / 365.0
), 2) as avg_career_span
FROM player 
WHERE debut IS NOT NULL AND debut != '' AND final_game IS NOT NULL AND final_game != ''
AND TRY_CAST(debut AS DATE) IS NOT NULL AND TRY_CAST(final_game AS DATE) IS NOT NULL", "preview_rows": 12}

